// ============================================================
// TutorBot · Modulo SOLICITAR (pasos 1-3 del wizard) + MOTOR DE ASIGNACION
// ============================================================
const ctx = $input.first().json;
const cfg = $('Config').first().json;

// --- Identidad unificada y defensiva ---
const userTelegram = String(ctx.telegram_user || ctx.chat_id || 'SIN_USUARIO');
const userChatId = String(ctx.chat_id || ctx.telegram_user || '');

const DUR          = Number(cfg.DURACION_MIN || 60);
const MAX_OPCIONES = Number(cfg.MAX_OPCIONES || 3);
const HORIZONTE    = Number(cfg.DIAS_MAX_ANTICIPACION || 30);
const DIAS = ['Domingo', 'Lunes', 'Martes', 'Miercoles', 'Jueves', 'Viernes', 'Sabado'];
const OCUPAN = ['ASIGNADA', 'CONFIRMADA'];

const norm = s => String(s == null ? '' : s).normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().trim();
const aMin = h => { const m = /^(\d{1,2}):(\d{2})/.exec(String(h == null ? '' : h).trim()); return m ? Number(m[1]) * 60 + Number(m[2]) : null; };
const aHora = m => String(Math.floor(m / 60)).padStart(2, '0') + ':' + String(m % 60).padStart(2, '0');
const diaDe = f => { const p = String(f || '').split('-').map(Number); return DIAS[new Date(Date.UTC(p[0], p[1] - 1, p[2])).getUTCDay()]; };
const aDias = f => { const p = String(f || '').split('-').map(Number); return Date.UTC(p[0], p[1] - 1, p[2]) / 86400000; };

function filas(nodo) {
  try { return $(nodo).all().map(i => i.json).filter(r => r && Object.keys(r).length > 0); }
  catch (e) { return []; }
}
const tutores  = filas('Leer TUTORES').filter(t => String(t.id_tutor || '') !== '');
const dispo    = filas('Leer DISPONIBILIDAD').filter(d => String(d.id_tutor || '') !== '');
const tutorias = filas('Leer TUTORIAS').filter(t => String(t.id_tutoria || '') !== '');

const materiasDe = t => String(t.especialidad_materias || '').split(/[;,|]/).map(s => s.trim()).filter(Boolean);
const activos = tutores.filter(t => norm(t.estado) === 'activo');

const catalogo = Array.from(new Map(
  activos.flatMap(materiasDe).map(m => [norm(m), m])
).values()).sort((a, b) => a.localeCompare(b, 'es'));

function sesion(pantalla, paso, datos) {
  return {
    telegram_user: userTelegram,
    pantalla_actual: pantalla,
    paso_actual: String(paso),
    datos_parciales: JSON.stringify(datos || {}),
    actualizado_en: String(cfg.ahora_iso || new Date().toISOString())
  };
}

function salida(o) {
  return [{ json: Object.assign({
    telegram_user: userTelegram,
    chat_id: userChatId,
    ruta: String(ctx.ruta || ''),
    submodo: String(ctx.submodo || ''),
    accion: 'sin_accion',
    estudiante_row: null,
    tutoria_row: null,
    notificar: null,
    evento: 'solicitud',
    detalle: ''
  }, o) }];
}

const listaMaterias = () => catalogo.map((m, i) => (i + 1) + ') ' + m).join('\n');

// ------------------------------------------------------------
// PASO 1 · Mostrar materias
// ------------------------------------------------------------
if (ctx.submodo === 'iniciar') {
  if (catalogo.length === 0) {
    return salida({
      mensaje: 'Ahora mismo no hay tutores activos con materias registradas. Avisa a la coordinacion academica.',
      sesion: sesion('MENU', 0, {}),
      evento: 'sin_catalogo'
    });
  }
  return salida({
    mensaje: '¿Sobre que materia necesitas la asesoria?\n\n' + listaMaterias() +
             '\n\nResponde con el numero. /cancelar para salir.',
    sesion: sesion('SOL_MATERIA', 1, { materias: catalogo }),
    evento: 'wizard_paso_materia'
  });
}

// ------------------------------------------------------------
// PASO 2 · Validar materia y pedir fecha
// ------------------------------------------------------------
if (ctx.submodo === 'materia') {
  const datosEntrada = ctx.datos || {};
  const ofrecidas = Array.isArray(datosEntrada.materias) && datosEntrada.materias.length ? datosEntrada.materias : catalogo;
  const n = parseInt(String(ctx.texto || '').replace(/[^0-9]/g, ''), 10);

  if (!n || n < 1 || n > ofrecidas.length) {
    return salida({
      mensaje: 'Necesito un numero entre 1 y ' + ofrecidas.length + '.\n\n' +
               ofrecidas.map((m, i) => (i + 1) + ') ' + m).join('\n'),
      sesion: sesion('SOL_MATERIA', 1, { materias: ofrecidas }),
      evento: 'materia_invalida',
      detalle: String(ctx.texto || '').slice(0, 20)
    });
  }
  const materia = ofrecidas[n - 1];
  return salida({
    mensaje: 'Materia: ' + materia + '.\n\n¿Para que fecha la necesitas?\n' +
             'Escribela en formato AAAA-MM-DD (ejemplo: ' + (cfg.hoy || '2026-09-07') + ').\n' +
             'Puedes pedirla hasta ' + HORIZONTE + ' dias adelante.',
    sesion: sesion('SOL_FECHA', 2, { materias: ofrecidas, materia: materia }),
    evento: 'wizard_paso_fecha',
    detalle: materia
  });
}

// ------------------------------------------------------------
// PASO 3 · Validar fecha y BUSCAR (motor de asignacion)
// ------------------------------------------------------------
const materia = String((ctx.datos && ctx.datos.materia) || '');
const f = String(ctx.texto || '').trim();

function reintentarFecha(msg) {
  return salida({
    mensaje: msg,
    sesion: sesion('SOL_FECHA', 2, ctx.datos || {}),
    evento: 'fecha_invalida',
    detalle: f.slice(0, 20)
  });
}

if (!/^\d{4}-\d{2}-\d{2}$/.test(f)) {
  return reintentarFecha('El formato no es valido. Usa AAAA-MM-DD, por ejemplo ' + (cfg.hoy || '2026-09-07') + '.');
}
const p = f.split('-').map(Number);
const d = new Date(Date.UTC(p[0], p[1] - 1, p[2]));
if (d.getUTCFullYear() !== p[0] || d.getUTCMonth() !== p[1] - 1 || d.getUTCDate() !== p[2]) {
  return reintentarFecha('Esa fecha no existe en el calendario. Revisa el dia y el mes.');
}
if (aDias(f) < aDias(cfg.hoy)) {
  return reintentarFecha('Esa fecha ya paso. Hoy es ' + cfg.hoy + '.');
}
if (aDias(f) - aDias(cfg.hoy) > HORIZONTE) {
  return reintentarFecha('Solo puedo agendar hasta ' + HORIZONTE + ' dias adelante. Elige una fecha mas cercana.');
}

const dia = diaDe(f);

function codigoTutoria(semilla, mias) {
  let h = 2166136261;
  const semStr = String(semilla || '');
  for (let i = 0; i < semStr.length; i++) {
    h ^= semStr.charCodeAt(i);
    h = Math.imul(h, 16777619);
  }
  let n = 1000000000 + (Math.abs(h) % 8999999999);
  if (n > 9999999999) n = 1000000000 + (n % 9000000000);

  const dueno = new Map(tutorias.map(t => [String(t.id_tutoria || ''), String(t.telegram_user_estudiante || '')]));
  let intentos = 0;
  while (dueno.has(String(n)) && dueno.get(String(n)) !== String(mias || '') && intentos < 2000) {
    n = n + 1 > 9999999999 ? 1000000000 : n + 1;
    intentos++;
  }
  return String(n);
}

const semillaInput = userTelegram + '|' + String(cfg.ahora_iso || '').replace(/[^0-9]/g, '').slice(0, 12);
const id_tutoria = codigoTutoria(semillaInput, userTelegram);

function filaBase(estado, motivo) {
  return {
    id_tutoria: id_tutoria,
    id_estudiante: String(ctx.id_estudiante || ''),
    nombre_estudiante: String(ctx.nombre_estudiante || ''),
    telegram_user_estudiante: userChatId || userTelegram,
    id_tutor: '', nombre_tutor: '',
    materia: materia, fecha: f, dia_semana: dia,
    hora: '', hora_fin: '', duracion_min: DUR,
    estado: estado, id_dispo: '',
    fecha_solicitud: String(cfg.ahora_iso || ''),
    fecha_actualizacion: String(cfg.ahora_iso || ''),
    recordatorio_enviado: '', motivo: motivo || ''
  };
}

function sinCupo(motivoTexto, motivoCodigo) {
  return salida({
    mensaje: motivoTexto + '\n\nPuedes intentar con otra fecha (opcion 1) o escribir /menu.',
    sesion: sesion('MENU', 0, {}),
    accion: 'crear_tutoria',
    tutoria_row: filaBase('SIN_DISPONIBILIDAD', motivoCodigo),
    evento: 'sin_disponibilidad',
    detalle: motivoCodigo + ' | ' + materia + ' | ' + f
  });
}

// RN-01 + RN-02
const candidatos = activos.filter(t => materiasDe(t).some(m => norm(m) === norm(materia)));
if (candidatos.length === 0) {
  return sinCupo('No hay ningun tutor activo para ' + materia + ' en este momento.', 'SIN_TUTOR_PARA_MATERIA');
}

// RN-03
const franjas = dispo.filter(x =>
  norm(x.dia_semana) === norm(dia) &&
  candidatos.some(t => String(t.id_tutor) === String(x.id_tutor)) &&
  ['libre', 'activa', 'activo', ''].includes(norm(x.estado))
);
if (franjas.length === 0) {
  return sinCupo('Los tutores de ' + materia + ' no atienden los ' + dia.toLowerCase() + '. Prueba con otro dia.', 'SIN_FRANJA_ESE_DIA');
}

// RN-04
const reservas = tutorias.filter(t => String(t.fecha) === f && OCUPAN.includes(String(t.estado || '').toUpperCase()));

// RN-05
const choca = (r, ini, fin) => {
  const ri = aMin(r.hora);
  if (ri === null) return false;
  const rf = aMin(r.hora_fin) !== null ? aMin(r.hora_fin) : ri + Number(r.duracion_min || DUR);
  return ini < rf && ri < fin;
};

const cargaTutor = id => tutorias.filter(t =>
  String(t.id_tutor) === String(id) && OCUPAN.includes(String(t.estado || '').toUpperCase())
).length;

const minutosAhora = aMin(cfg.hora_actual) || 0;
let opciones = [];
for (const fr of franjas) {
  const ini = aMin(fr.hora_inicio), fin = aMin(fr.hora_fin);
  if (ini === null || fin === null || fin <= ini) continue;
  for (let s = ini; s + DUR <= fin; s += DUR) {
    const e = s + DUR;
    if (f === cfg.hoy && s <= minutosAhora) continue;
    if (reservas.some(r => String(r.id_tutor) === String(fr.id_tutor) && choca(r, s, e))) continue;
    if (reservas.some(r => String(r.id_estudiante) === String(ctx.id_estudiante || '') && choca(r, s, e))) continue;
    const t = candidatos.find(x => String(x.id_tutor) === String(fr.id_tutor));
    opciones.push({
      id_dispo: String(fr.id_dispo || ''), id_tutor: String(fr.id_tutor),
      nombre_tutor: String(t ? t.nombre : fr.id_tutor),
      hora: aHora(s), hora_fin: aHora(e), carga: cargaTutor(fr.id_tutor)
    });
  }
}

if (opciones.length === 0) {
  return sinCupo('Todos los horarios de ' + materia + ' para el ' + f + ' (' + dia.toLowerCase() + ') estan ocupados.', 'TODO_OCUPADO');
}

// RN-08
opciones.sort((a, b) =>
  a.hora.localeCompare(b.hora) || a.carga - b.carga || a.id_tutor.localeCompare(b.id_tutor)
);
const vistos = new Set();
const primeraVuelta = opciones.filter(o => !vistos.has(o.id_tutor) && vistos.add(o.id_tutor));
const finales = primeraVuelta.concat(opciones.filter(o => !primeraVuelta.includes(o))).slice(0, MAX_OPCIONES);

const detalle = finales.map((o, i) =>
  (i + 1) + ') ' + o.hora + ' a ' + o.hora_fin + ' con ' + o.nombre_tutor
).join('\n');

return salida({
  mensaje: [
    'Encontre ' + finales.length + ' opcion(es) para ' + materia + ' el ' + f + ' (' + dia.toLowerCase() + '):',
    '',
    detalle,
    '',
    'Responde con el numero para confirmar, o 0 para descartar.'
  ].join('\n'),
  sesion: sesion('SOL_CONFIRMA', 3, {
    materia: materia, fecha: f, dia: dia, id_tutoria: id_tutoria, opciones: finales
  }),
  accion: 'crear_tutoria',
  tutoria_row: filaBase('SOLICITADA', ''),
  evento: 'opciones_ofrecidas',
  detalle: materia + ' | ' + f + ' | ' + finales.length + ' opciones'
});

// ============================================================
// TutorBot · Normalizar respuesta del modulo
// Punto unico de convergencia de los 7 modulos. Garantiza que, sin importar
// que rama se ejecuto, exista siempre: mensaje, sesion, accion y fila de log.
// Hay una copia de este nodo por rama: 'Normalizar REGISTRO', 'Normalizar MENU', etc.
// Los nodos siguientes de cada rama leen del suyo, no de uno compartido.
// ============================================================
const it = $input.first().json;
const cfg = $('Config').first().json;

// ---- Rastro de la IA (si esta ejecucion paso por el interprete) ----
// $('Nodo') lanza error si el nodo no se ejecuto en esta rama: se captura.
// En el sub-workflow el contexto llega por 'Ejecutar modulo'; en un flujo unico
// viene del nodo de validacion. Se prueban los dos y se ignora el que no exista.
let ia = null;
for (const nombre of ['Ejecutar modulo', 'Validar interpretacion IA']) {
  try {
    const j = $(nombre).first().json;
    if (j && j.ia_usada) { ia = j; break; }
  } catch (e) { /* ese nodo no existe en este workflow */ }
}

const ACCIONES = ['sin_accion', 'crear_estudiante', 'crear_tutoria', 'actualizar_tutoria'];
const accion = ACCIONES.includes(it.accion) ? it.accion : 'sin_accion';

// Telegram rechaza mensajes vacios y corta en 4096 caracteres
let mensaje = String(it.mensaje == null ? '' : it.mensaje).trim();
if (!mensaje) mensaje = 'Ocurrio algo inesperado y no pude preparar una respuesta. Escribe /menu para reiniciar.';
// El estudiante debe VER lo que el modelo entendio antes de que se reserve nada
if (ia && ia.ia_aviso) mensaje = ia.ia_aviso + '\n\n' + mensaje;
// Telegram interpreta el texto como HTML: hay que escapar estos tres caracteres.
// Sin esto, un "<" en el texto rompe el envio entero con "can't parse entities".
const esc = t => String(t == null ? '' : t).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
mensaje = esc(mensaje);
if (mensaje.length > 3900) mensaje = mensaje.slice(0, 3900) + '\n\n[mensaje recortado]';

const sesion = it.sesion || {
  telegram_user: it.telegram_user, pantalla_actual: 'MENU', paso_actual: '0',
  datos_parciales: '{}', actualizado_en: cfg.ahora_iso
};

const tutoria = it.tutoria_row || null;
const estudiante = it.estudiante_row || null;

let entidad = 'sesion', id_entidad = String(it.telegram_user || '');
if (tutoria)        { entidad = 'tutoria';    id_entidad = String(tutoria.id_tutoria || ''); }
else if (estudiante){ entidad = 'estudiante'; id_entidad = String(estudiante.id_estudiante || ''); }

// Fila de LOG_EVENTOS: es la trazabilidad que pide la coordinacion
const log = {
  id_evento: 'EV-' + String(cfg.ahora_iso).replace(/[^0-9]/g, '').slice(0, 14) + '-' + Math.floor(Math.random() * 9000 + 1000),
  timestamp: cfg.ahora_iso,
  telegram_user: String(it.telegram_user || ''),
  evento: String(it.evento || 'interaccion'),
  entidad: entidad,
  id_entidad: id_entidad,
  detalle: String(it.detalle == null ? '' : it.detalle).slice(0, 300)
};
// Auditoria del uso de IA: que se le mando, que devolvio y si se acepto
if (ia) {
  log.detalle = (log.detalle + ' | IA:' + ia.ia_intencion +
    '/' + (ia.ia_materia || '-') + '/' + (ia.ia_fecha || '-') +
    ' conf=' + ia.ia_confianza +
    (ia.ia_fallo ? ' descartado=' + ia.ia_fallo : '') +
    ' txt="' + String(ia.ia_texto_original || '').slice(0, 60) + '"').slice(0, 300);
}

return [{
  json: {
    telegram_user: String(it.telegram_user || ''),
    chat_id: String(it.chat_id || ''),
    ruta: it.ruta || '', submodo: it.submodo || '',
    mensaje: mensaje,
    sesion: sesion,
    accion: accion,
    estudiante_row: estudiante,
    tutoria_row: tutoria,
    notificar: it.notificar && it.notificar.chat_id
      ? Object.assign({}, it.notificar, { mensaje: esc(it.notificar.mensaje) })
      : null,
    ia_usada: !!ia,
    ia_fallo: ia ? ia.ia_fallo : '',
    log: log
  }
}];
